(function(E){ const x = E["ai-m1"] = E["ai-m1"] || {units:{}}; x.units["ai-5"] = {"grammar":{"id":"c-ai-5-g","level":"B1","course":"ai-internet","unit":"ai-5","title":"Staying with the text: based only on, according to, it says","titleTr":"Metne bağlı kalmak: based only on, according to, it says","titleFa":"به متن پایبند بمان: based only on، according to، it says","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Based only on + noun","Based only on this page, list the dates."],["If it is not in the text, say so.","If it is not in the text, say so."],["Section 2 says that...","Section 2 says that returns take 14 days."]]},"wrong":"Based only in the document, list the points.","right":"Based only on the document, list the points.","blank":{"sentence":"___ only on this page, list the prices.","word":"Based","distractors":["Basing","Base"]},"wrong2":"If it isn't in the text, say it so.","right2":"If it isn't in the text, say so.","blank2":{"sentence":"If you can't find it, ___ so.","word":"say","distractors":["tell","speak"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Put based only on at the start of the request.","tr":"based only on'u isteğin başına koy.","fa":"based only on را اول درخواست بگذار.","ex":"Based only on this contract, list the dates."},{"en":"Say so means say that it is not there.","tr":"say so, orada olmadığını söylemek demektir.","fa":"say so یعنی بگو که آنجا نیست.","ex":"If you can't find it, say so."}],"test":{"en":"Does your request name the text it must use?","tr":"İsteğin kullanılacak metni söylüyor mu?","fa":"درخواستت می‌گوید از کدام متن استفاده شود؟"}},"errorWatch":[{"find":["based only in"],"fix":{"en":"Say \"based only on\".","tr":"\"based only on\" de.","fa":"بگو «based only on»."}}]},"b2":{"id":"c-ai-5-b2","level":"B2","course":"ai-internet","unit":"ai-5","track":"B2","title":"Reporting a text: states, mentions, does not specify","titleTr":"Metni aktarmak: states, mentions, does not specify","titleFa":"نقل متن: states، mentions، does not specify","formsTable":{"headers":{"en":["Verb","Example"],"tr":["Fiil","Örnek"],"fa":["فعل","مثال"]},"rows":[["states","The report states that sales fell."],["mentions","It mentions a delay."],["does not specify","It does not specify the date."]]},"wrong":"The report does not specifies the date.","right":"The report does not specify the date.","blank":{"sentence":"The page does not ___ the delivery time.","word":"specify","distractors":["specifies","specifying"]},"wrong2":"It mentions about a delay.","right2":"It mentions a delay.","blank2":{"sentence":"The email ___ a change of address.","word":"mentions","distractors":["mentions about","mention about"]},"expParts":{"tryFrom":"blank","rule":[{"en":"States is strong and clear.","tr":"states güçlü ve nettir.","fa":"فعل states محکم و روشن است.","ex":"The contract states that..."},{"en":"Does not specify means the detail is missing.","tr":"does not specify, ayrıntının eksik olduğunu söyler.","fa":"does not specify یعنی آن جزئیات نیامده.","ex":"It does not specify the price."}],"test":{"en":"Is the detail really missing? Use does not specify.","tr":"Ayrıntı gerçekten eksik mi? does not specify kullan.","fa":"آن جزئیات واقعاً نیامده؟ از does not specify استفاده کن."}},"errorWatch":[{"find":["mentions about"],"fix":{"en":"Mention has no about: \"mentions a delay\".","tr":"mention about ile kullanılmaz: \"mentions a delay\".","fa":"بعد از mention کلمه‌ی about نمی‌آید: «mentions a delay»."}}],"useIn":{"en":"B2: report one thing the text states, and one thing it does not specify.","tr":"B2: Metnin söylediği bir şeyi ve belirtmediği bir şeyi aktar.","fa":"B2: یک چیز را که متن گفته و یک چیز را که مشخص نکرده نقل کن."},"exitItem":{"from":"ai-5","kind":"blank","prompt":"The contract does not ___ who pays for delivery.","options":["specify","specifies","specified to"],"correct":0}},"vocab":{"id":"c-ai-5-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-5","goals":["career"],"title":{"en":"Working from documents","tr":"Belgelerle çalışmak","fa":"کار با سندها"},"cards":[{"word":"Upload","sentence":"Upload the report, then ask about it.","meaning":{"en":"Send a file from your device to the tool","tr":"Cihazından araca dosya gönder","fa":"فایلی را از دستگاهت به ابزار بفرست"}},{"word":"Projects","sentence":"Projects keep the documents for one job together.","meaning":{"en":"Separate workspaces with their own chats and documents","tr":"Kendi sohbetleri ve belgeleri olan ayrı çalışma alanları","fa":"فضاهای کاری جدا با چت‌ها و سندهای خودشان"}},{"word":"Incognito chat","sentence":"An Incognito chat is still kept for a time.","meaning":{"en":"A chat that stays out of your history and isn't used for training. It is still kept for a time.","tr":"Geçmişinde görünmeyen ve eğitimde kullanılmayan sohbet. Yine de bir süre saklanır.","fa":"چتی که در تاریخچه‌ات نمی‌ماند و برای آموزش استفاده نمی‌شود. با این حال مدتی نگه داشته می‌شود."}},{"word":"Usage limit","sentence":"You may wait when you reach the usage limit.","meaning":{"en":"How much you can use it before you must wait","tr":"Beklemen gerekmeden önce ne kadar kullanabileceğin","fa":"چقدر می‌توانی از آن استفاده کنی، پیش از آنکه مجبور شوی صبر کنی"}},{"word":"section","sentence":"The price is in section 3.","meaning":{"en":"One part of a document.","tr":"Bir belgenin bir bölümü.","fa":"یک بخش از سند."}},{"word":"main point","sentence":"List the main points of this report.","meaning":{"en":"An important idea in a text.","tr":"Bir metindeki önemli fikir.","fa":"ایده‌ی مهم یک متن."}},{"word":"instructions","sentence":"Save your instructions in the project.","meaning":{"en":"What you tell a tool to do each time.","tr":"Araca her seferinde ne yapacağını söylediğin şeyler.","fa":"چیزهایی که هر بار به ابزار می‌گویی چه کند."}}]},"judge":{"id":"c-ai-5-j","course":"ai-internet","unit":"ai-5","type":"judge","title":{"en":"Is it on the page?","tr":"Sayfada var mı?","fa":"در صفحه هست؟"},"prompt":"Page: \"Our office is open Monday to Friday, 9:00 to 17:00. The support team answers within two working days.\" Example AI answers below.","parts":["On the page","Different on the page","Not on the page"],"instruction":{"en":"Compare each line with the page.","tr":"Her satırı sayfayla karşılaştır.","fa":"هر خط را با صفحه مقایسه کن."},"mode":"single","screen":{"id":"scr-claude-1","src":"courses/ai-internet/assets/scr-claude-1.webp?v=44050ce34a","alt":"Our drawing of a Claude-style chat screen, November 2026, not a screenshot. Projects in the side list, an uploaded one-page file, a message box and a plus button to add a file."},"items":[{"by":"Example AI answer","answer":"The office is open from Monday to Friday.","present":["On the page"],"fix":{"en":"Yes, same fact.","tr":"Evet, aynı bilgi.","fa":"بله، همان اطلاعات است."}},{"by":"Example AI answer","answer":"Support answers within two days.","present":["Different on the page"],"fix":{"en":"The page says two working days.","tr":"Sayfada two working days yazıyor.","fa":"در صفحه two working days آمده است."}},{"by":"Example AI answer","answer":"You can also call us on Saturday.","present":["Not on the page"],"fix":{"en":"It invented this. Remove it.","tr":"Bunu uydurdu. Çıkar.","fa":"این را از خودش ساخته. حذفش کن."}},{"by":"Example AI answer","answer":"Support closes at 17:00 every day of the year.","present":["Different on the page"],"fix":{"en":"The page gives office hours, Monday to Friday only.","tr":"Sayfada yalnızca hafta içi ofis saatleri var.","fa":"در صفحه فقط ساعت کار دفتر در روزهای کاری آمده."}}]},"speaking":{"id":"ai-5","course":"ai-internet","unit":"ai-5","topic":{"en":"Say what the document says","tr":"Belgenin ne dediğini söyle","fa":"بگو سند چه می‌گوید"},"warmup":{"en":"What is a long document you must read at work?","tr":"İşinde okuman gereken uzun bir belge hangisi?","fa":"چه سند بلندی را باید در کارت بخوانی؟"},"questions":[{"en":"Tell a colleague why you check an AI summary against the document, with one example.","tr":"Bir meslektaşına yapay zekâ özetini neden belgeyle karşılaştırdığını bir örnekle anlat.","fa":"به همکارت بگو چرا خلاصه‌ی هوش مصنوعی را با سند مقایسه می‌کنی و یک مثال بزن."},{"en":"The tool's summary says \"free returns\". The document doesn't. Say what you do.","tr":"Aracın özeti \"free returns\" diyor. Belge böyle demiyor. Ne yapacağını söyle.","fa":"خلاصه‌ی ابزار می‌گوید «free returns». سند چنین چیزی نگفته. بگو چه می‌کنی."},{"en":"Tell a colleague what you would save as instructions for one weekly job.","tr":"Bir meslektaşına, haftalık bir iş için talimat olarak neyi kaydedeceğini anlat.","fa":"به همکارت بگو برای یک کار هفتگی چه چیزی را به‌عنوان دستور ذخیره می‌کنی."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"The document says that...","meaning":{"en":"Reports the text.","tr":"Metni aktarır.","fa":"متن را نقل می‌کند."}},{"phrase":"It isn't in the document.","meaning":{"en":"Says a fact is missing.","tr":"Bir bilginin olmadığını söyler.","fa":"می‌گوید این مطلب در سند نیست."}}],"model":"I always check an AI summary against the document. Last week an answer said the refund takes thirty days. The document says that it takes fourteen days, so I corrected it. The answer also mentioned a free return label, but it isn't in the document, so I removed it. It sounded good, and it was wrong.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I gave a real example of a check.","tr":"Gerçek bir kontrol örneği verdim.","fa":"یک مثال واقعی از بررسی زدم."}]},"writing":{"id":"c-ai-5-w","title":{"en":"Write a prompt for one page","tr":"Tek sayfa için prompt yaz","fa":"برای یک صفحه پرامپت بنویس"},"course":"ai-internet","unit":"ai-5","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Write a prompt for this one-page policy: \"Staff may work from home on Fridays. Ask your manager by Wednesday. Laptops must stay locked.\" Ask for the main points, and say what to do if something is missing.","tr":"Şu tek sayfalık kural için prompt yaz: \"Staff may work from home on Fridays. Ask your manager by Wednesday. Laptops must stay locked.\" Ana noktaları iste ve eksik bir şey varsa ne yapılacağını söyle.","fa":"برای این آیین‌نامه‌ی یک‌صفحه‌ای پرامپت بنویس: «Staff may work from home on Fridays. Ask your manager by Wednesday. Laptops must stay locked.» نکته‌های اصلی را بخواه و بگو اگر چیزی نبود چه کند."},"model":"Based only on the policy below, list the three main points for new staff. Keep each point under 12 words. If something is not in the policy, write \"not in the document\".","frame":"Based only on ___, list ___ for ___. If something is not in ___, write \"not in the document\".","words":[{"word":"Based only on"},{"word":"not in the document"}],"minWords":20,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Ask it to report one thing the policy does not specify.","tr":"B2 yolu: hazır çerçeve yok. Kuralın belirtmediği bir şeyi aktarmasını iste.","fa":"مسیر B2: چارچوب آماده نداری. از ابزار بخواه یک چیز را بگوید که آیین‌نامه مشخص نکرده است."},"own":{"en":"Now write the same kind of prompt for a one-page document from your job. Remove private details first.","tr":"Şimdi işinden tek sayfalık bir belge için aynı türden prompt yaz. Önce özel bilgileri çıkar.","fa":"حالا برای یک سند یک‌صفحه‌ای از کارت همین نوع پرامپت را بنویس. اول جزئیات خصوصی را حذف کن."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Run it, then check every point against the page. Mark Keep, Correct, or Remove.","tr":"Çalıştır, sonra her noktayı sayfayla karşılaştır. Keep, Correct ya da Remove yaz.","fa":"پرامپت را اجرا کن، بعد هر نکته را با صفحه مقایسه کن و Keep، Correct یا Remove بنویس."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the example answers in this lesson.","tr":"Bu dersteki örnek yanıtları kullan.","fa":"از جواب‌های نمونه‌ی همین درس استفاده کن."},"noTool":true}]},"exit":{"id":"c-ai-5-x","course":"ai-internet","unit":"ai-5","type":"exit","items":[{"from":"ai-5","kind":"mcq","prompt":"What does Anthropic say Claude does not create?","options":["Drafts of long emails","Summaries of files","Photos and illustrations"],"correct":2,"why":{"en":"It can make diagrams and charts, but not photos or illustrations.","tr":"Şema ve grafik yapabilir ama fotoğraf ya da illüstrasyon üretmez.","fa":"می‌تواند نمودار بسازد، ولی عکس و تصویرسازی نه."},"point":2},{"from":"ai-5","kind":"blank","prompt":"___ only on this report, list the risks.","options":["Base","Basing","Based"],"correct":2,"why":{"en":"The phrase is based only on.","tr":"Kalıp based only on.","fa":"عبارت درست based only on است."},"point":6},{"from":"ai-5","kind":"mcq","prompt":"After you say \"based only on\", what must you still do?","options":["Nothing. It can't guess now.","Check every point against the page.","Pay for a plan."],"correct":1,"why":{"en":"It makes guessing less likely. It doesn't stop it.","tr":"Tahmini azaltır, önlemez.","fa":"حدس زدن را کمتر می‌کند، ولی جلویش را نمی‌گیرد."},"point":4},{"from":"ai-4","kind":"mcq","prompt":"Which line is a clear limit?","options":["Under 60 words.","Not too long, please.","Make it short-ish."],"correct":0,"why":{"en":"A number is clearer than a word like short.","tr":"Sayı \"short\" gibi bir kelimeden daha nettir.","fa":"عدد از کلمه‌ای مثل short روشن‌تر است."}},{"from":"ai-3","kind":"mcq","prompt":"Which of these stays out of any AI tool?","options":["A public price list","Our opening hours","The admin password"],"correct":2,"why":{"en":"Passwords never go in.","tr":"Parolalar asla girmez.","fa":"رمز عبور را هرگز وارد ابزار نکن."}},{"from":"ai-2","kind":"mcq","prompt":"You see \"Something went wrong\". What do you do first?","options":["Change the language.","Try again.","Buy a paid plan."],"correct":1,"why":{"en":"The tool had a problem, so try again.","tr":"Araçta sorun oldu, yeniden dene.","fa":"ابزار دچار مشکل شده، پس دوباره امتحان کن."}},{"from":"ai-5","kind":"mcq","prompt":"You paste the same instructions every week. What saves the most work?","options":["Save them with your files in the tool.","Write them again with fewer words.","Ask a colleague to paste them for you."],"correct":0,"why":{"en":"Each new chat then starts ready. Still test it.","tr":"Böylece her yeni sohbet hazır başlar. Yine de test et.","fa":"این‌طوری هر چت جدید آماده شروع می‌شود. باز هم آزمایشش کن."},"point":5}]},"explain":{"id":"c-ai-5-e","course":"ai-internet","unit":"ai-5","type":"explain","level":"B1","title":{"en":"Claude: work from your own document","tr":"Claude: kendi belgenden çalış","fa":"⁨Claude⁩: بر اساس سند خودت کار کن"},"objective":{"en":"After this lesson, you can ask a tool to answer only from your document, and check the answer against the page.","tr":"Bu dersin sonunda bir araçtan yalnızca belgene dayanarak yanıt isteyebilecek ve yanıtı sayfayla karşılaştırabileceksin.","fa":"بعد از این درس می‌توانی از ابزار بخواهی فقط از سندت جواب بدهد و جواب را با صفحه مقایسه کنی."},"hook":{"en":"A tool can answer from its own guesses. You can ask it to use your text, and then check that it did.","tr":"Bir araç kendi tahminlerinden yanıt verebilir. Metnini kullanmasını isteyip kullandığını kontrol edebilirsin.","fa":"ابزار ممکن است از حدس‌های خودش جواب بدهد. می‌توانی از آن بخواهی از متن تو استفاده کند و بعد ببینی این کار را کرده یا نه."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"6"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What Claude is","tr":"Claude nedir","fa":"⁨Claude⁩ چیست"},"body":{"en":"Claude is a general AI assistant made by the company Anthropic. You can use it in a browser or in its apps. It can answer questions, write and analyse text.","tr":"Claude, Anthropic şirketinin yaptığı genel bir yapay zekâ asistanıdır. Tarayıcıda ya da uygulamalarında kullanabilirsin. Soruları yanıtlayabilir, yazı yazabilir ve metin çözümleyebilir.","fa":"⁨Claude⁩ یک دستیار عمومی هوش مصنوعی است که شرکت ⁨Anthropic⁩ آن را ساخته. می‌توانی در مرورگر یا اپلیکیشن‌هایش از آن استفاده کنی. می‌تواند به سؤال‌ها جواب بدهد، بنویسد و متن را تحلیل کند."},"steps":[{"en":"It reads a file you upload and answers about it in the same chat.","tr":"Yüklediğin dosyayı okur ve aynı sohbette onun hakkında yanıt verir.","fa":"فایلی را که آپلود می‌کنی می‌خواند و در همان چت درباره‌اش جواب می‌دهد.","ex":"+ then Add files or photos"},{"en":"A Project keeps one job's chats and files together.","tr":"Project, bir işin sohbetlerini ve dosyalarını bir arada tutar.","fa":"⁨Project⁩ چت‌ها و فایل‌های یک کار را کنار هم نگه می‌دارد.","ex":"Projects"}],"tip":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."}},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What it is good for, and not","tr":"Neye yarar, neye yaramaz","fa":"به چه کاری می‌آید و به چه کاری نه"},"steps":[{"en":"Questions about long documents you upload","tr":"Yüklediğin uzun belgeler hakkında sorular","fa":"سؤال درباره‌ی سندهای طولانی‌ای که آپلود می‌کنی","ex":"What does this contract say about delivery?"},{"en":"Drafting and editing text","tr":"Metin taslağı yazmak ve düzenlemek","fa":"نوشتن پیش‌نویس و ویرایش متن","ex":"Make this clearer. Keep my style."},{"en":"Not the best: photos and illustrations. Anthropic says Claude doesn't create them.","tr":"En iyisi değil: Fotoğraf ve illüstrasyon. Anthropic, Claude'un bunları üretmediğini söylüyor.","fa":"بهترین گزینه نیست: عکس و تصویرسازی. ⁨Anthropic⁩ می‌گوید ⁨Claude⁩ این‌ها را نمی‌سازد.","ex":"Need a photo? Use an image maker."},{"en":"Not the best: work inside your Gmail or Word. Look first at the assistant made for that place.","tr":"En iyisi değil: Gmail ya da Word içindeki işler. Önce o yer için yapılmış asistana bak.","fa":"بهترین گزینه نیست: کار داخل ⁨Gmail⁩ یا ⁨Word⁩. اول سراغ دستیاری برو که برای همان‌جا ساخته شده.","ex":"Mail in Outlook? Look at Copilot."}]},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"How to start","tr":"Nasıl başlanır","fa":"چطور شروع کنی"},"steps":[{"en":"Go to claude.ai, or open the app.","tr":"claude.ai adresine git ya da uygulamayı aç.","fa":"به ⁨claude.ai⁩ برو یا اپلیکیشن را باز کن."},{"en":"Sign up or log in. Anthropic says you must be at least 18 and in a supported location.","tr":"Kaydol ya da giriş yap. Anthropic, en az 18 yaşında olman ve desteklenen bir yerde bulunman gerektiğini söylüyor.","fa":"ثبت‌نام کن یا وارد شو. ⁨Anthropic⁩ می‌گوید باید دست‌کم ۱۸ ساله باشی و در منطقه‌ای باشی که پشتیبانی می‌شود."},{"en":"Type your message. Use + to add a file.","tr":"Mesajını yaz. Dosya eklemek için + düğmesini kullan.","fa":"پیامت را بنویس. برای اضافه کردن فایل از + استفاده کن."},{"en":"Ask about the file in the same chat.","tr":"Dosyayla ilgili soruları aynı sohbette sor.","fa":"سؤال‌های مربوط به فایل را در همان چت بپرس."}],"phrases":[{"phrase":"Based only on the document I uploaded, list the five main points.\nFor each point, give the page or section.\nIf something is not in the document, write \"not in the document\".","meaning":{"en":"You can upload the document, and page numbers let you check each point.","tr":"Belgeyi yükleyebilirsin; sayfa numaraları her noktayı kontrol etmeni sağlar.","fa":"می‌توانی سند را آپلود کنی و شماره‌ی صفحه‌ها کمک می‌کنند هر نکته را بررسی کنی."},"copy":true}],"tip":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}},{"head":{"en":"Keep the tool inside your text","tr":"Aracı metninin içinde tut","fa":"کاری کن ابزار فقط از متن تو جواب بدهد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"With no text, a tool writes likely words (Lesson 1.1). Give it your document and tell it to use only that. Then it invents less.","tr":"Metin yoksa araç olası kelimeler yazar (Ders 1.1). Belgeni ver ve yalnızca onu kullanmasını söyle. Böylece daha az uydurur.","fa":"بدون متن، ابزار کلمه‌های محتمل می‌نویسد (درس ۱.۱). سندت را به آن بده و بگو فقط از همان استفاده کند. این‌طوری کمتر چیزی از خودش می‌سازد."},"steps":[{"en":"Say where the answer must come from, or it may guess.","tr":"Yanıtın nereden gelmesi gerektiğini söyle, yoksa tahmin edebilir.","fa":"بگو جواب باید از کجا بیاید، وگرنه ممکن است حدس بزند.","ex":"Based only on the document below..."},{"en":"Say what to do when something isn't there, or it may fill the gap.","tr":"Bir şey yoksa ne yapılacağını söyle, yoksa boşluğu doldurabilir.","fa":"بگو اگر چیزی نبود چه کند، وگرنه ممکن است جای خالی را پر کند.","ex":"If something is not in the document, write \"not in the document\"."},{"en":"Ask for the page or section, so you can check.","tr":"Kontrol edebilmek için sayfa ya da bölüm iste.","fa":"از ابزار بخواه شماره‌ی صفحه یا بخش را هم بگوید تا بتوانی بررسی کنی.","ex":"For each point, give the section."}],"phrases":[{"phrase":"Based only on the document below, list the three main points. If something is not in the document, write \"not in the document\".","meaning":{"en":"Copy this prompt. It works on other tools too.","tr":"Bu prompt'u kopyala. Başka araçlarda da işe yarar.","fa":"این پرامپت را کپی کن. در ابزارهای دیگر هم کار می‌کند."},"copy":true}]},{"head":{"en":"Save your instructions","tr":"Talimatlarını kaydet","fa":"دستورهایت را ذخیره کن"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Do you paste the same instructions every week? Many tools let you save them with your files. Then each new chat starts ready, like a custom assistant.","tr":"Aynı talimatları her hafta yapıştırıyor musun? Birçok araç bunları dosyalarınla birlikte kaydetmene izin verir. Böylece her yeni sohbet hazır başlar; sana özel bir asistan gibi.","fa":"هر هفته همان دستورها را می‌چسبانی؟ خیلی از ابزارها اجازه می‌دهند آن‌ها را همراه فایل‌هایت ذخیره کنی. این‌طوری هر چت جدید آماده شروع می‌شود، مثل یک دستیار مخصوص خودت."},"steps":[{"en":"In the instructions, say how it must work, so you don't repeat them.","tr":"Talimatlarda nasıl çalışması gerektiğini söyle, böylece tekrar etmezsin.","fa":"در دستورها بگو چطور کار کند، تا لازم نباشد هر بار تکرارشان کنی.","ex":"Answer only from these files. Under 100 words."},{"en":"Add only public or approved files, because they stay in the tool.","tr":"Yalnızca herkese açık ya da onaylı dosyalar ekle, çünkü araçta kalırlar.","fa":"فقط فایل‌های عمومی یا تأییدشده را اضافه کن، چون داخل ابزار می‌مانند.","ex":"Price list, return policy"},{"en":"Test it with three questions you can answer, so you can see any mistake.","tr":"Yanıtını bildiğin üç soruyla test et, böylece hatayı görürsün.","fa":"با سه سؤال که جوابشان را می‌دانی آزمایشش کن، تا اگر اشتباه کرد ببینی.","ex":"How long do returns take?"}],"phrases":[{"phrase":"Answer only from the files in this project. If the answer is not in them, write \"not in the files\". Use plain English, under 100 words. Give the file name for each point.","meaning":{"en":"Instructions to save. Change them for your job.","tr":"Kaydedilecek talimatlar. İşine göre değiştir.","fa":"دستورهایی برای ذخیره کردن. آن‌ها را مطابق کارت تغییر بده."},"copy":true}],"tip":{"en":"Names differ and change: Projects in Claude, agents in Copilot, skills in Gemini. At work, ask before you share one.","tr":"Adlar farklıdır ve değişir: Claude'da Projects, Copilot'ta agents, Gemini'da skills. İş yerinde, paylaşmadan önce sor.","fa":"نام‌ها فرق دارند و عوض می‌شوند: در ⁨Claude⁩ می‌گویند ⁨Projects⁩، در ⁨Copilot⁩ می‌گویند ⁨agents⁩ و در ⁨Gemini⁩ می‌گویند ⁨skills⁩. در محل کار، پیش از اینکه آن را با دیگران به اشتراک بگذاری، بپرس."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Staying with the text: based only on, according to, it says","tr":"Metne bağlı kalmak: based only on, according to, it says","fa":"به متن پایبند بمان: ⁨based only on⁩، ⁨according to⁩، ⁨it says⁩"},"steps":[{"en":"Put based only on at the start of the request.","tr":"based only on'u isteğin başına koy.","fa":"⁨based only on⁩ را اول درخواست بگذار.","ex":"Based only on this contract, list the dates."},{"en":"Say so means say that it is not there.","tr":"say so, orada olmadığını söylemek demektir.","fa":"⁨say so⁩ یعنی بگو که آنجا نیست.","ex":"If you can't find it, say so."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Based only on + noun","Based only on this page, list the dates."],["If it is not in the text, say so.","If it is not in the text, say so."],["Section 2 says that...","Section 2 says that returns take 14 days."]]},"wrong":"According to the document, it says the fee is 40 euros.","right":"According to the document, the fee is 40 euros."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Check an answer against the page","tr":"Yanıtı sayfayla karşılaştır","fa":"جواب را با صفحه مقایسه کن"},"item":"Page: \"Returns within 14 days. Bring your receipt.\"\nAnswer: \"Returns within 30 days. You need a receipt and the original box.\"","answer":"Correct \"30 days\" to \"14 days\". Remove \"the original box\": it is not on the page.","walk":[{"en":"Read the answer one line at a time.","tr":"Yanıtı satır satır oku.","fa":"جواب را خط‌به‌خط بخوان."},{"en":"Find each fact on the page.","tr":"Her bilgiyi sayfada bul.","fa":"هر نکته را در صفحه پیدا کن."},{"en":"Not on the page? Remove it or ask.","tr":"Sayfada yok mu? Çıkar ya da sor.","fa":"در صفحه نیست؟ حذفش کن یا بپرس."}],"why":{"en":"The first answer looked complete, but two facts did not come from the page. After the check it says only what the page says.","tr":"İlk yanıt eksiksiz görünüyordu ama iki bilgi sayfadan gelmiyordu. Kontrolden sonra yalnızca sayfanın söylediğini söylüyor.","fa":"جواب اول کامل به نظر می‌آمد، ولی دو مطلبش از صفحه نیامده بود. بعد از بررسی فقط همان چیزی را می‌گوید که در صفحه هست."}},"quick":{"prompt":"You have a 60-page policy PDF and one question about it. Claude is open. What do you do first?","options":["Upload the file, then ask about it.","Ask from memory: it knows most policies.","Paste only the title of the policy."],"correct":0,"why":{"en":"With the file it has real text to work from.","tr":"Dosyayla çalışacak gerçek bir metni olur.","fa":"وقتی فایل را به آن بدهی، متن واقعی برای کار دارد."}},"quickAfter":3,"remember":{"en":"\"Based only on\" makes guessing less likely but doesn't stop it, so check every point against the page. You can now get answers from your own document and save your instructions for a job you repeat.","tr":"\"Based only on\" tahmini azaltır ama önlemez, bu yüzden her noktayı sayfayla karşılaştır. Artık kendi belgenden yanıt alabilir ve tekrarladığın bir iş için talimatlarını kaydedebilirsin.","fa":"«⁨Based only on⁩» حدس زدن را کمتر می‌کند، ولی جلویش را نمی‌گیرد؛ پس هر نکته را با صفحه مقایسه کن. حالا می‌توانی از سند خودت جواب بگیری و دستورهایت را برای کاری که تکرار می‌کنی ذخیره کنی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Reporting a text: states, mentions, does not specify","tr":"Metni aktarmak: states, mentions, does not specify","fa":"نقل متن: ⁨states⁩، ⁨mentions⁩، ⁨does not specify⁩"},"steps":[{"en":"States is strong and clear.","tr":"states güçlü ve nettir.","fa":"فعل ⁨states⁩ محکم و روشن است.","ex":"The contract states that..."},{"en":"Does not specify means the detail is missing.","tr":"does not specify, ayrıntının eksik olduğunu söyler.","fa":"⁨does not specify⁩ یعنی آن جزئیات نیامده.","ex":"It does not specify the price."}],"table":{"headers":{"en":["Verb","Example"],"tr":["Fiil","Örnek"],"fa":["فعل","مثال"]},"rows":[["states","The report states that sales fell."],["mentions","It mentions a delay."],["does not specify","It does not specify the date."]]},"body":{"en":"B2: report one thing the text states, and one thing it does not specify.","tr":"B2: Metnin söylediği bir şeyi ve belirtmediği bir şeyi aktar.","fa":"⁨B2⁩: یک چیز را که متن گفته و یک چیز را که مشخص نکرده نقل کن."}},"tool":"claude"}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
